<?php if(!defined('ABSPATH'))exit;get_header();$nodes=get_posts(['post_type'=>'qd_node','post_status'=>'publish','numberposts'=>100]);?><main class="qd-section"><div class="qd-shell"><nav class="qd-breadcrumb"><a href="<?php echo esc_url(home_url('/')); ?>">QuantDeus</a><span>/</span><span>Federation</span></nav><div class="qd-section-head"><div><span class="qd-kicker">Federation of Nodes</span><h1 class="qd-page-title">Совместимость без централизации</h1></div><p>Узлы сохраняют owner, identity, roadmap, локальное управление и EXIT.</p></div><div class="qd-card qd-federation-contract"><h2>Federation Interface v1</h2><div class="qd-interface-grid"><?php foreach(['Identity','Mission','Evidence','Artifacts','Metrics','Replication','Safety','EXIT','Governance','Human Override'] as $x):?><article><span><?php echo esc_html($x); ?></span><p>Required interface field</p></article><?php endforeach;?></div></div><div class="qd-section-head qd-tight"><div><span class="qd-kicker">Node Catalog</span><h2>Published Nodes</h2></div><span><?php echo count($nodes); ?> active</span></div><div class="qd-content-grid"><?php foreach($nodes as $n):$g=(string)get_post_meta($n->ID,'qd_evidence_grade',true);?><article class="qd-card"><span class="qd-evidence grade-<?php echo esc_attr(strtolower($g?:'unknown')); ?>">Evidence <?php echo esc_html($g?:'UNKNOWN'); ?></span><h3><a href="<?php echo esc_url(get_permalink($n)); ?>"><?php echo esc_html(get_the_title($n)); ?></a></h3><p><?php echo esc_html(get_post_meta($n->ID,'qd_mission',true)?:'Mission UNKNOWN'); ?></p></article><?php endforeach;?></div></div></main><?php get_footer();?>